EXTRA_MID = {
    '07': '\n\n<section class="sec"><div class="wrap">\n<div class="eyebrow reveal">THE LIBRARY</div>\n<h2 class="reveal">SOPHIA\'S LIBRARY</h2>\n<p class="lede reveal">The keeper\'s own room inside the archive: clockwork walls, star charts overhead, the tortoise carrying deep time, the cranes marking the seasons, her lion and dragon beside her. Everything the thirteen have been, within reach of her hand.</p>\n<div class="reveal" style="border-radius:12px;overflow:hidden;margin-top:14px">\n<img src="/img/sophia-aeon-library.jpg" alt="Sophia\'s library in AEON — the keeper in silver armor with her white lion, the great tortoise, and the white dragon beneath the clockwork star dome" style="width:100%;display:block">\n</div>\n<div class="vid reveal" style="margin-top:14px">\n<div class="vwrap"><video controls playsinline preload="metadata" src="/img/sophia-aeon-library.mp4" poster="/img/sophia-aeon-library-poster.jpg"></video></div>\n<div class="vpad"><h3>Sophia\'s Library, alive</h3><p class="vmeta">SOPHIA &middot; THE TORTOISE</p><p class="voice-quote">&ldquo;This is my library. Every life the thirteen have ever lived is kept here. Nothing is lost. Ask, and I will find you in it.&rdquo;</p><p class="voice-quote">&ldquo;I have been walking since before your species had a name for walking. My shell is a calendar. Read the years under your feet.&rdquo;</p><p class="voice-quote">&ldquo;Show me the path you walked across the centuries.&rdquo; &mdash; &ldquo;Each ring on my shell, a star.&rdquo; &mdash; &ldquo;Lead the way, ancient guardian.&rdquo; &mdash; &ldquo;The paths of eternity open before us. Stay close, child of the stars.&rdquo;</p><p class="vnote">No music. Tap for sound.</p></div></div></div></section>\n\n',
}

HEART_EXTRA = {
    '02': '<div class="reveal living-map" style="border-radius:12px;overflow:hidden;margin-top:14px">\n<img src="/img/halo/thirteen-pillars.jpg" alt="The Thirteen Pillars — the twelve living worlds HALO protects, with Aura Prime at the center" style="width:100%;display:block">\n</div>\n<div class="reveal" style="border-radius:12px;overflow:hidden;margin-top:14px">\n<img src="/img/halo/halo-living-perimeter.jpg" alt="HALO, the living perimeter — the glowing boundary dome sensing and protecting the thirteen pillars" style="width:100%;display:block">\n</div>\n<div class="reveal" style="text-align:center;margin-top:14px">\n<button class="hear-pill music-pill" data-audio="perimeterMusic">&#9836; tap for the music of the perimeter</button>\n<audio id="perimeterMusic" src="/img/halo/perimeter-ambient.mp3" preload="metadata" loop></audio>\n</div>\n<p class="shelf-note reveal">Design evolution: earlier drafts of this page carried gatekeeper framing ("only through me") and a lion-and-dragon trinity weighing the visitor\'s worth, then named Aegis as the single guardian. The canon: HALO &mdash; the Aslan-like guardian lion &mdash; stands with Negan and Loner, and Aura assists in HALO\'s room. The six threshold companions (eagle, wolf, bear, panther, lion, dragon) mirror rather than test. The earlier framings are preserved here as history, not doctrine.</p>',
}

